  const fresh=()=>({version:1,year:new Date().getFullYear(),month:new Date().toISOString().slice(0,7),metric:'sales',titles:{...names},indicatorText:{},values:{},saGross:{},objectivePlans:{[base.year]:M.emptyPlan(base)},scales:{},cashiers:{},roReports:{}});
  let state=fresh(),objectiveDraft=null;
