  try{const saved=localStorage.getItem(KEY);if(saved){const parsed=JSON.parse(saved);if(parsed?.version===1&&parsed.values&&parsed.cashiers&&(parsed.objectivePlans||parsed.goals))state=migrate(parsed);}}catch{}
  const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
