  function attendance(month){const rows=state.cashiers[month]||[];return {visits:rows.length?rows.reduce((s,r)=>s+r.visits,0):null,amount:rows.length?rows.reduce((s,r)=>s+r.amount,0):null,rows};}
  const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().replace(/\s+/g,' ').toUpperCase();
