  function roSummary(month){const income=reportValue('Total Ingresos',month),exploit=reportValue('Costos de Explotación',month),commissions=reportValue('Comisiones',month),ro=reportValue('Resultado Operacional',month),costs=Number.isFinite(exploit)&&Number.isFinite(commissions)?Math.abs(exploit)-Math.abs(commissions):null;return {income,exploit:Number.isFinite(exploit)?Math.abs(exploit):null,commissions:Number.isFinite(commissions)?Math.abs(commissions):null,costs,ro};}
  function format(value,metric){if(value===null||value===undefined||!Number.isFinite(value))return '—';if(units[metric]==='percent')return percent.format(value);if(units[metric]==='count')return num.format(value);return money.format(value);}
  function persist(){try{state.year=Number($('year').value)||state.year;state.month=selectedMonth();state.metric=$('metric').value;state.titles[state.metric]=$('title').value.trim()||names[state.metric];localStorage.setItem(KEY,JSON.stringify(state));}catch{showMessage('No se pudo guardar en este navegador.',true);}}
