  function drawChart(){const metric=state.metric,year=Number($('year').value)||state.year,scale=range(),zero=Math.max(scale.min,Math.min(scale.max,0)),pos=v=>100*(v-scale.min)/(scale.max-scale.min),base=pos(zero);
    $('chart').innerHTML=months.map((label,i)=>{const key=monthKey(year,i),v=getValue(metric,key),g=getGoal(metric,key),cl=status(v,g),p=v===null?zero:pos(Math.max(scale.min,Math.min(scale.max,v))),bottom=Math.min(base,p),height=Math.abs(p-base);const gp=g===null?null:pos(Math.max(scale.min,Math.min(scale.max,g)));return `<div class="month-col" title="${escape(label+' '+year)} · Resultado: ${escape(format(v,metric))} · Objetivo: ${escape(g===null?'Sin objetivo':format(g,metric))}"><div class="bar-area">${gp===null?'':`<span class="goal-line" style="bottom:${gp}%"></span>`}<span class="bar ${cl==='empty'?'empty':cl==='none'?'none':''}" style="bottom:${bottom}%;height:${v===null?0:Math.max(height,1)}%;background:${cl==='good'?'#70AD47':cl==='bad'?'#ff0000':cl==='none'?'#050505':'#fff'}"></span></div><span class="month-label">${shortMonths[i]}</span><span class="month-value">${escape(format(v,metric))}</span></div>`;}).join('');
  }
  function openAttendance(){ $('attendancePaste').value='';$('attendanceError').hidden=true;$('attendancePreview').textContent=`El reporte reemplazará las filas de ${months[Number(state.month.slice(5))-1]} ${state.month.slice(0,4)}.`;$('attendanceDialog').showModal(); }
  function parseLocaleNumber(raw){let s=String(raw??'').trim().replace(/\s/g,'').replace(/\$/g,'');if(!s)return 0;if(s.includes(',')&&s.includes('.'))s=s.replace(/\./g,'').replace(',','.');else if(s.includes(','))s=s.replace(',','.');else if((s.match(/\./g)||[]).length>1)s=s.replace(/\./g,'');else if(/\.\d{3}$/.test(s))s=s.replace('.','');const n=Number(s);return Number.isFinite(n)?n:NaN;}
  function parseAttendance(text){const out=[],errors=[];for(const [i,line] of text.split(/\r?\n/).entries()){if(!line.trim())continue;const c=line.split('\t').map(s=>s.trim());if(c.length<3){errors.push(`Fila ${i+1}: faltan columnas.`);continue;}const name=c[0].replace(/^\u00a0+|\u00a0+$/g,'').trim(),visits=parseLocaleNumber(c[1]),amount=parseLocaleNumber(c[2]);if(/^(cajero|nombre)$/i.test(name)||/^(atenciones|total atenciones)$/i.test(c[1]))continue;if(!name||!Number.isFinite(visits)||visits<0||!Number.isFinite(amount)||amount<0){errors.push(`Fila ${i+1}: revisa cajero, atenciones y monto.`);continue;}out.push({name,visits,amount});}if(!out.length&&!errors.length)errors.push('No se encontraron filas para guardar.');return {out,errors};}
  const parseXml=text=>{const d=new DOMParser().parseFromString(text,'application/xml');if(d.querySelector('parsererror'))throw Error('La planilla contiene XML inválido.');return d;};
  function columnIndex(ref){let n=0;for(const ch of ref.match(/^[A-Z]+/)[0])n=n*26+ch.charCodeAt(0)-64;return n;}
  function monthFromHeader(v){if(typeof v==='number'){const d=new Date(Date.UTC(1899,11,30)+Math.round(v)*86400000);return d.toISOString().slice(0,7);}const s=String(v??'').trim();if(/^\d{4}-\d{2}$/.test(s))return s;const d=s.match(/^(\d{1,2})[\/-](\d{4})$/);if(d&&+d[1]>=1&&+d[1]<=12)return `${d[2]}-${d[1].padStart(2,'0')}`;return null;}
  async function readROWorkbook(file,targetYear){const zip=await JSZip.loadAsync(await file.arrayBuffer()),get=async path=>{const f=zip.file(path);if(!f)throw Error(`No se encontró ${path} en la planilla.`);return f.async('string');},wb=parseXml(await get('xl/workbook.xml')),rels=parseXml(await get('xl/_rels/workbook.xml.rels'));let shared=[];if(zip.file('xl/sharedStrings.xml')){const ss=parseXml(await get('xl/sharedStrings.xml'));shared=[...ss.getElementsByTagName('si')].map(si=>[...si.getElementsByTagName('t')].map(t=>t.textContent).join(''));}const sheetNode=[...wb.getElementsByTagName('sheet')].find(s=>norm(s.getAttribute('name'))==='RESULTADO OPERACIONAL')||wb.getElementsByTagName('sheet')[0];if(!sheetNode)throw Error('La planilla no contiene hojas.');const rid=sheetNode.getAttribute('r:id'),rel=[...rels.getElementsByTagName('Relationship')].find(r=>r.getAttribute('Id')===rid);if(!rel)throw Error('No se encontró la hoja seleccionada.');let target=rel.getAttribute('Target').replace(/^\//,'');if(!target.startsWith('xl/'))target='xl/'+target;while(target.includes('../'))target=target.replace(/[^/]+\/\.\.\//,'');const doc=parseXml(await get(target)),sheetName=sheetNode.getAttribute('name')||'Hoja 1',rows=[...doc.getElementsByTagName('row')],cells=new Map();for(const row of rows){const rn=Number(row.getAttribute('r')),map=new Map();for(const c of [...row.getElementsByTagName('c')]){const ref=c.getAttribute('r'),type=c.getAttribute('t'),v=c.getElementsByTagName('v')[0]?.textContent??'';let value=null;if(type==='inlineStr')value=[...c.getElementsByTagName('t')].map(t=>t.textContent).join('');else if(type==='s')value=shared[Number(v)]??'';else if(type==='str')value=v;else if(v!==''){const n=Number(v);value=Number.isFinite(n)?n:v;}map.set(columnIndex(ref),value);}cells.set(rn,map);}const header=cells.get(9);if(!header)throw Error('No encontré los meses en la fila 9.');const maxCol=Math.max(...header.keys()),periods=[];for(let col=2;col<=maxCol;col++){const month=monthFromHeader(header.get(col));if(month)periods.push({col,month:monthKey(targetYear,Number(month.slice(5))-1)});}if(!periods.length)throw Error('No pude detectar meses en los encabezados de la fila 9.');const items=[];for(const [rn,map] of cells){if(rn<10)continue;const name=String(map.get(1)??'').trim();if(!name)continue;const values={};let hasValue=false;for(const p of periods){const raw=map.get(p.col),v=typeof raw==='number'?raw:raw===null||raw===''?null:parseLocaleNumber(raw);values[p.month]=Number.isFinite(v)?v:null;if(Number.isFinite(v))hasValue=true;}if(hasValue||name)items.push({id:`ro-${rn}-${Math.random().toString(36).slice(2,8)}`,name,values});}if(!items.length)throw Error('No encontré conceptos en la columna A.');for(const item of items)if(norm(item.name)==='COSTOS DE EXPLOTACION')for(const month of Object.keys(item.values))if(Number.isFinite(item.values[month]))item.values[month]=Math.abs(item.values[month]);return {fileName:file.name,sheetName,year:Number(targetYear),months:periods.map(p=>p.month),items};}
  $('metric').onchange=()=>{state.metric=$('metric').value;$('title').value=state.titles[state.metric]||names[state.metric];persist();render();};
