  $('attendancePaste').oninput=()=>{const p=parseAttendance($('attendancePaste').value);$('attendancePreview').textContent=p.errors.length?p.errors.join('\n'):`${p.out.length} filas listas · ${num.format(p.out.reduce((s,r)=>s+r.visits,0))} atenciones · ${money.format(p.out.reduce((s,r)=>s+r.amount,0))}`;$('attendancePreview').classList.toggle('error',p.errors.length>0);};
  $('attendanceForm').onsubmit=e=>{e.preventDefault();const p=parseAttendance($('attendancePaste').value);if(p.errors.length){$('attendanceError').textContent=p.errors.join(' ');$('attendanceError').hidden=false;return;}state.cashiers[state.month]=p.out;persist();render();$('attendanceDialog').close();showMessage(`Reporte guardado para ${months[Number(state.month.slice(5))-1]} ${state.year}.`);};
