  $('roFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const targetYear=Number($('roImportYear').value);if(!Number.isInteger(targetYear)||targetYear<2000||targetYear>2100)throw Error('Selecciona un año válido entre 2000 y 2100.');const report=await readROWorkbook(file,targetYear);state.roReports??={};state.roReports[String(targetYear)]=report;const last=report.months.at(-1);$('year').value=targetYear;$('month').value=last;persist();render();$('roImportDialog').close();showMessage(`Planilla cargada para ${targetYear}: ${report.items.length} conceptos y ${report.months.length} meses.`);}catch(error){$('roImportError').textContent=error.message;$('roImportError').hidden=false;}finally{$('roFile').value='';}};
