  function exportPayload(metric,year){const texts=currentTexts(metric,year);if(metric==='roPercent')texts.definition+='; el RO en pesos se informa en la fila anterior al porcentaje.';return {metric,year,title:state.titles[metric]||names[metric],definition:texts.definition,texts,unit:units[metric],scale:rangeFor(metric,year),periods:exportPeriods(year).map(key=>{const priorKey=monthKey(Number(key.slice(0,4))-1,Number(key.slice(5))-1);return {key,label:shortMonths[Number(key.slice(5))-1].toUpperCase(),value:getValue(metric,key),goal:getGoal(metric,key),roValue:getValue('ro',key),priorYearValue:metric==='roPercent'?null:getValue(metric,priorKey),priorYearRO:metric==='roPercent'?getValue('ro',priorKey):null,priorYearPercent:metric==='roPercent'?getValue('roPercent',priorKey):null};})};}
  async function exportCurrent(){const y=Number($('year').value),m=state.metric;download(await MORWorkbookExport.one(window.INDICADOR_TEMPLATE,exportPayload(m,y)),`MOR-${m}-${y}.xlsx`);}
  async function exportData(){download(await makeXlsx(dataSheets()),`MOR-Datos-${Number($('year').value)}.xlsx`);}
  function openExport(mode){$('exportModeLabel').textContent=mode==='pdf'?'PDF · MÁXIMO 4 INDICADORES POR PÁGINA':'UN SOLO LIBRO EXCEL';$('exportSubmit').textContent=mode==='pdf'?'Descargar PDF':'Descargar libro';$('exportChoices').innerHTML=Object.entries(names).map(([key,label])=>`<label class="multi-export-choice"><input type="checkbox" data-export="${key}" ${key===state.metric?'checked':''}><span>${label}</span></label>`).join('');$('exportError').hidden=true;$('multiExportDialog').dataset.mode=mode;updateExportCount();$('multiExportDialog').showModal();}
  function updateExportCount(){const n=$('exportChoices').querySelectorAll('input:checked').length,mode=$('multiExportDialog').dataset.mode;$('exportCount').textContent=`${n} indicadores seleccionados${mode==='pdf'?` · ${Math.ceil(n/4)} páginas`:''}`;$('exportSubmit').disabled=!n;}
  $('exportCurrent').onclick=async()=>{const b=$('exportCurrent');b.disabled=true;try{await exportCurrent();}catch(e){showMessage(`No se pudo exportar el indicador: ${e.message}`,true);}finally{b.disabled=false;}};
  $('exportData').onclick=async()=>{const b=$('exportData');b.disabled=true;try{await exportData();}catch(e){showMessage(`No se pudieron exportar los datos: ${e.message}`,true);}finally{b.disabled=false;}};
  $('exportMany').onclick=()=>openExport('excel');$('exportPdf').onclick=()=>openExport('pdf');$('exportChoices').onchange=updateExportCount;$('exportSelectAll').onclick=()=>{$('exportChoices').querySelectorAll('input').forEach(i=>i.checked=true);updateExportCount();};$('exportSelectNone').onclick=()=>{$('exportChoices').querySelectorAll('input').forEach(i=>i.checked=false);updateExportCount();};
  function canvasPage(metrics,year,page,total){const c=document.createElement('canvas');c.width=1684;c.height=1190;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.fillStyle='#191919';x.font='bold 36px Arial';x.fillText(`MOR · REUNIÓN MENSUAL ${year} · OCT–DIC ${year-1} + ENE–DIC ${year}`,55,55);metrics.forEach((metric,index)=>{const col=index%2,row=Math.floor(index/2),cx=55+col*805,cy=90+row*535,w=775,h=500;x.fillStyle='#f7f7f7';x.fillRect(cx,cy,w,h);x.strokeStyle='#555';x.strokeRect(cx,cy,w,h);x.fillStyle='#111';x.font='bold 24px Arial';x.fillText((state.titles[metric]||names[metric]).slice(0,46),cx+18,cy+35);const bounds=rangeFor(metric,year),min=bounds.min,max=bounds.max,keys=exportPeriods(year),barX=cx+43,chartY=cy+80,chartH=300,slot=45,bw=25,basePos=Math.max(0,Math.min(1,(0-min)/(max-min)));for(let i=0;i<keys.length;i++){const key=keys[i],v=getValue(metric,key),g=getGoal(metric,key),s=status(v,g),p=v===null?basePos:Math.max(0,Math.min(1,(v-min)/(max-min))),bh=chartH*Math.abs(p-basePos),by=chartY+chartH-chartH*Math.max(p,basePos),bx=barX+i*slot;x.fillStyle=s==='good'?'#70AD47':s==='bad'?'#ff0000':s==='none'?'#111':'#fff';x.fillRect(bx,by,bw,bh);x.strokeStyle='#333';x.strokeRect(bx,by,bw,bh);if(g!==null){const gy=chartY+chartH-chartH*Math.max(0,Math.min(1,(g-min)/(max-min)));x.strokeStyle='#222';x.beginPath();x.moveTo(bx-3,gy);x.lineTo(bx+bw+3,gy);x.stroke();}x.fillStyle='#222';x.font='10px Arial';x.fillText(periodShort(key),bx-8,chartY+chartH+19);x.font='9px Arial';const f=format(v,metric);x.fillText(f.length>8?f.slice(0,8):f,bx-8,chartY+chartH+34);if(metric==='roPercent'){x.font='8px Arial';x.fillText('RO '+format(getValue('ro',key),'ro'),bx-8,chartY+chartH+47);}}x.fillStyle='#555';x.font='12px Arial';x.fillText('Barras mensuales · línea oscura: objetivo',cx+18,cy+h-17);});x.fillStyle='#444';x.font='14px Arial';x.fillText(`Página ${page} de ${total}`,c.width-145,c.height-24);return c;}
  function rangeFor(metric,year){return scaleFor(metric,state.scales[metric]);}
  async function canvasJpeg(canvas){return new Promise((resolve,reject)=>canvas.toBlob(async b=>{if(!b){reject(Error('No se pudo crear la página del PDF.'));return;}resolve(new Uint8Array(await b.arrayBuffer()));},'image/jpeg',.92));}
  function bytesConcat(chunks){const n=chunks.reduce((s,b)=>s+b.length,0),out=new Uint8Array(n);let at=0;for(const b of chunks){out.set(b,at);at+=b.length;}return out;}
  function pdfFromJpegs(images){const enc=new TextEncoder(),objs=[];objs[1]=enc.encode('<< /Type /Catalog /Pages 2 0 R >>');const kids=images.map((_,i)=>`${4+i*3} 0 R`).join(' ');objs[2]=enc.encode(`<< /Type /Pages /Kids [${kids}] /Count ${images.length} >>`);images.forEach((jpeg,i)=>{const pageId=4+i*3,imgId=pageId+1,contentId=pageId+2;objs[pageId]=enc.encode(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 841.89 595.28] /Resources << /XObject << /Im0 ${imgId} 0 R >> >> /Contents ${contentId} 0 R >>`);objs[imgId]=bytesConcat([enc.encode(`<< /Type /XObject /Subtype /Image /Width 1684 /Height 1190 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\nstream\n`),jpeg,enc.encode('\nendstream')]);const stream='q 841.89 0 0 595.28 0 0 cm /Im0 Do Q';objs[contentId]=enc.encode(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);});const chunks=[enc.encode('%PDF-1.4\n% MOR\n')],offsets=[0];let offset=chunks[0].length;for(let i=1;i<objs.length;i++){offsets[i]=offset;const head=enc.encode(`${i} 0 obj\n`),tail=enc.encode('\nendobj\n');chunks.push(head,objs[i],tail);offset+=head.length+objs[i].length+tail.length;}const xref=offset;let table=`xref\n0 ${objs.length}\n0000000000 65535 f \n`;for(let i=1;i<objs.length;i++)table+=`${String(offsets[i]).padStart(10,'0')} 00000 n \n`;table+=`trailer\n<< /Size ${objs.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;chunks.push(enc.encode(table));return new Blob([bytesConcat(chunks)],{type:'application/pdf'});}
  async function exportPdf(metrics){const year=Number($('year').value)||state.year,pages=[];for(let i=0;i<metrics.length;i+=4)pages.push(await canvasJpeg(canvasPage(metrics.slice(i,i+4),year,pages.length+1,Math.ceil(metrics.length/4))));download(pdfFromJpegs(pages),`MOR-Indicadores-${year}.pdf`);}
  $('multiExportForm').onsubmit=async e=>{e.preventDefault();const selected=[...$('exportChoices').querySelectorAll('input:checked')].map(i=>i.dataset.export);if(!selected.length)return;$('exportSubmit').disabled=true;$('exportError').hidden=true;try{const year=Number($('year').value)||state.year;if($('multiExportDialog').dataset.mode==='pdf')await exportPdf(selected);else await MORWorkbookExport.many(window.INDICADOR_TEMPLATE,selected.map(metric=>exportPayload(metric,year))).then(blob=>download(blob,`MOR-Indicadores-${year}.xlsx`));}catch(error){$('exportError').textContent=`No se pudo exportar: ${error.message}`;$('exportError').hidden=false;}finally{$('exportSubmit').disabled=false;updateExportCount();}};
  $('backup').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`Respaldo-MOR-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);};
  $('restore').onclick=()=>$('restoreFile').click();$('restoreFile').onchange=async e=>{try{const f=e.target.files?.[0];if(!f)return;const d=JSON.parse(await f.text());if(d?.version!==1||!d.values||!d.cashiers||!(d.objectivePlans||d.goals))throw Error('El archivo no corresponde a un respaldo MOR.');state=migrate(d);$('year').value=state.year;$('month').value=state.month;$('metric').value=state.metric;$('title').value=state.titles[state.metric]||names[state.metric];persist();render();showMessage('Respaldo MOR restaurado.');}catch(err){showMessage(err.message||'No se pudo abrir el respaldo.',true);}finally{$('restoreFile').value='';}};
  document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
  $('year').value=state.year;$('month').value=/^[0-9]{4}-[0-9]{2}$/.test(state.month)?state.month:`${state.year}-01`;$('metric').value=names[state.metric]?state.metric:'sales';$('title').value=state.titles[state.metric]||names[state.metric];render();
